python_template.create_page:
```python
import requests

NOTION_TOKEN = 'ваш_токен'
PARENT_PAGE_ID = 'id_родительской_страницы'

headers = {
    'Authorization': f'Bearer {NOTION_TOKEN}',
    'Content-Type': 'application/json',
    'Notion-Version': '2026-03-11'
}

page_data = {
    'parent': { 'page_id': PARENT_PAGE_ID },
    'properties': {
        'title': { 'title': [{ 'text': { 'content': 'Заголовок страницы' } }] }
    },
    'children': [
        {
            'object': 'block',
            'type': 'heading_1',
            'heading_1': { 'rich_text': [{ 'text': { 'content': 'Подзаголовок' } }] }
        },
        {
            'object': 'block',
            'type': 'paragraph',
            'paragraph': { 'rich_text': [{ 'text': { 'content': 'Текст абзаца' } }] }
        }
    ]
}

response = requests.post('https://api.notion.com/v1/pages', headers=headers, json=page_data)
print(response.json())
```

